<script setup lang="ts">
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { FilePenLine, Plus, Save } from 'lucide-vue-next'
import JournalTabs from '../components/JournalTabs.vue'
import ProjectAttendees from '../components/ProjectAttendees.vue'
import Pager from '../components/Pager.vue'
import DraftNotice from '../components/DraftNotice.vue'
import ConflictNotice from '../components/ConflictNotice.vue'
import HistoryPanel from '../components/HistoryPanel.vue'
import { useConflict, useDraft } from '../drafts'
import { api, isProjectReadOnly, localDate, messageOf, notify, projectName, query, softDelete, ui } from '../api'
import { queuePrintExport, queueWordExport } from '../exports'
import type { MeetingMinute, Page } from '../types'

const props=defineProps<{revision:number}>()
const emit=defineEmits<{changed:[]}>()
const items=ref<MeetingMinute[]>([]),total=ref(0),offset=ref(0),loading=ref(false),error=ref(''),saving=ref(false),exporting=ref(false),opening=ref(false),editor=ref(false),editing=ref<MeetingMinute>()
const filters=reactive({project_id:'',q:'',date_from:'',date_to:'',unclassified:false})
const applied=ref<Record<string,string|number|undefined>>({})
const form=reactive({project_id:'',title:'',meeting_date:localDate(),location:'',attendees:'',content:''})
const limit=20
let listRequest=0,entityRequest=0
const readonly=computed(()=>isProjectReadOnly(editing.value?.project_id||'')||isProjectReadOnly(form.project_id)||(!!editing.value?.project_id&&ui.projectsLoaded&&!ui.projects.some(p=>p.id===editing.value?.project_id)))
const local=useDraft(()=>`meeting-minutes:${editing.value?.id||'new'}`,form,()=>editor.value,()=>editing.value?.version)
const conflict=useConflict()
const busy=computed(()=>saving.value||exporting.value||opening.value)
function canLeave(){return !busy.value&&(!editor.value||local.canLeave())}
async function load(){const request=++listRequest;loading.value=true;try{const page=await api<Page<MeetingMinute>>(`/api/meeting-minutes?${query({...applied.value,limit,offset:offset.value})}`);if(request===listRequest){items.value=page.items;total.value=page.total;if(offset.value>=page.total&&offset.value>0){offset.value=0;await load()}}}catch(e){if(request===listRequest)error.value=messageOf(e)}finally{if(request===listRequest)loading.value=false}}
async function apply(){error.value='';offset.value=0;applied.value={q:filters.q.trim(),project_id:filters.unclassified?'':filters.project_id,date_from:filters.date_from,date_to:filters.date_to,...(filters.unclassified?{unclassified:'1'}:{})};await load()}
async function create(){if(!canLeave())return;entityRequest++;local.persist();editing.value=undefined;Object.assign(form,{project_id:filters.unclassified||isProjectReadOnly(filters.project_id)?'':filters.project_id,title:'',meeting_date:localDate(),location:'',attendees:'',content:''});editor.value=true;error.value='';conflict.clear();await local.reset()}
async function select(id:string){if(!canLeave())return;const request=++entityRequest;opening.value=true;error.value='';try{const latest=await api<MeetingMinute>(`/api/meeting-minutes/${encodeURIComponent(id)}`);if(request!==entityRequest)return;local.persist();editing.value=latest;Object.assign(form,{project_id:latest.project_id||'',title:latest.title,meeting_date:latest.meeting_date,location:latest.location||'',attendees:latest.attendees||'',content:latest.content});editor.value=true;conflict.clear();await local.reset()}catch(e){if(request===entityRequest)error.value=messageOf(e)}finally{if(request===entityRequest)opening.value=false}}
async function save(){if(busy.value||readonly.value||!form.title.trim()||!form.meeting_date||!form.content.trim())return;saving.value=true;error.value='';const payload={...form,...(editing.value?{version:editing.value.version}:{})};try{const saved=await api<MeetingMinute>(editing.value?`/api/meeting-minutes/${editing.value.id}`:'/api/meeting-minutes',{method:editing.value?'PATCH':'POST',body:JSON.stringify(payload)});local.discard();editing.value=saved;Object.assign(form,{project_id:saved.project_id||'',title:saved.title,meeting_date:saved.meeting_date,location:saved.location||'',attendees:saved.attendees||'',content:saved.content});conflict.clear();await local.reset();notify('会议纪要已保存');emit('changed');await load()}catch(e){error.value=messageOf(e);local.persist();if(editing.value)await conflict.capture(e,`/api/meeting-minutes/${editing.value.id}`,payload)}finally{saving.value=false}}
async function reloadConflict(){const remote=conflict.current.value?.remote as unknown as MeetingMinute;if(!remote)return;local.persist();editing.value=remote;Object.assign(form,{project_id:remote.project_id||'',title:remote.title,meeting_date:remote.meeting_date,location:remote.location||'',attendees:remote.attendees||'',content:remote.content});conflict.clear();await local.reset();error.value='已载入新纪要，原修改保留在浏览器草稿中。'}
async function remove(){if(!editing.value||readonly.value||!canLeave())return;saving.value=true;error.value='';try{if(await softDelete('meeting-minutes',editing.value,editing.value.title)){local.discard();editor.value=false;editing.value=undefined;emit('changed');await load()}}catch(e){error.value=messageOf(e);local.persist();if(editing.value)await conflict.capture(e,`/api/meeting-minutes/${editing.value.id}`,form)}finally{saving.value=false}}
async function exportSaved(print=false){if(!editing.value||busy.value||local.dirty.value)return;exporting.value=true;error.value='';try{if(print)await queuePrintExport('meeting_minutes',editing.value);else await queueWordExport('meeting_minutes',editing.value)}catch(e){error.value=messageOf(e)}finally{exporting.value=false}}
function restoreDraft(){local.restore();editor.value=true}
function page(next:number){offset.value=next;void load()}
onMounted(()=>void load());watch(()=>props.revision,()=>void load())
defineExpose({canLeave,openEntity:select})
</script>
<template>
<div class="page-heading"><div><h1>工作日志</h1><p class="page-description">记录会议讨论、决定和后续安排，保留每次修改与已保存的版本。</p></div><button type="button" class="button primary" :disabled="busy" @click="create"><Plus :size="16"/>新建纪要</button></div>
<JournalTabs active="meetings"/>
<form class="filter-bar meeting-filters" @submit.prevent="apply"><label class="sr-only" for="meeting-filter-project">筛选纪要项目</label><select id="meeting-filter-project" v-model="filters.project_id" :disabled="filters.unclassified"><option value="">全部项目</option><option v-for="p in ui.projects" :key="p.id" :value="p.id">{{p.name}}</option></select><label class="checkbox-label"><input v-model="filters.unclassified" type="checkbox"/>未归类</label><label class="sr-only" for="meeting-filter-from">会议开始日期</label><input id="meeting-filter-from" v-model="filters.date_from" type="date" aria-label="会议开始日期"/><span class="muted">至</span><label class="sr-only" for="meeting-filter-to">会议结束日期</label><input id="meeting-filter-to" v-model="filters.date_to" type="date" aria-label="会议结束日期" :min="filters.date_from||undefined"/><label class="sr-only" for="meeting-filter-query">搜索会议纪要</label><input id="meeting-filter-query" v-model="filters.q" maxlength="200" placeholder="标题、正文或参会人"/><button class="button subtle" :disabled="loading">查询</button></form>
<div v-if="error" class="error-banner" role="alert">{{error}}</div><p v-if="conflict.error.value" class="form-error" role="alert">{{conflict.error.value}}</p>
<div class="worklog-layout meeting-layout"><aside class="surface saved-logs"><div class="section-heading"><h2>已保存纪要 <span class="count">{{total}}</span></h2></div><p v-if="loading" class="loading-message">正在读取纪要…</p><div v-else-if="!items.length" class="empty-state compact"><FilePenLine :size="30"/><p>没有符合条件的纪要。可调整筛选，或新建一份会议纪要。</p></div><div v-else class="log-list meeting-list"><button v-for="item in items" :key="item.id" type="button" :disabled="busy" :class="{selected:editing?.id===item.id}" @click="select(item.id)"><span class="log-date">{{item.meeting_date}}</span><strong>{{item.title}}</strong><span>{{item.project_id?projectName(item.project_id):'未归类'}}<template v-if="item.location"> · {{item.location}}</template></span></button></div><Pager :offset="offset" :limit="limit" :total="total" @change="page"/></aside>
<section class="surface log-editor meeting-editor"><template v-if="editor"><div class="section-heading"><div><h2>{{editing?'会议纪要':'新建会议纪要'}} <span v-if="local.dirty.value" class="draft-label">未保存</span></h2><p class="input-hint">{{editing?.code||'保存后生成编号'}}<span v-if="readonly"> · 项目已结项或归档，只读</span></p></div><div class="row-actions"><button v-if="editing" type="button" class="button subtle small" :disabled="busy||local.dirty.value" @click="exportSaved(false)">导出 Word</button><button v-if="editing" type="button" class="button subtle small" :disabled="busy||local.dirty.value" @click="exportSaved(true)">打印 / PDF</button><button v-if="editing&&!readonly" type="button" class="button subtle small" :disabled="busy" @click="remove">移入回收站</button><button v-if="!readonly" type="submit" form="meeting-form" class="button primary small" :disabled="busy||!form.title.trim()||!form.content.trim()||!form.meeting_date"><Save :size="15"/>{{saving?'正在保存…':'保存纪要'}}</button></div></div>
<div class="meeting-notices"><DraftNotice :value="local.available.value" :values="local.values.value" :error="local.storageError.value" :recovery="local.recovery.value" @select="local.select" @restore="restoreDraft" @force="local.restoreForced" @cancel-recovery="local.clearRecovery" @discard="local.discardAvailable"/><ConflictNotice :value="conflict.current.value" @keep="local.persist();conflict.clear()" @reload="reloadConflict"/></div>
<form id="meeting-form" @submit.prevent="save"><fieldset :disabled="busy||readonly"><div class="meeting-fields"><label>会议标题 <span class="required">*</span><input v-model="form.title" required maxlength="500" placeholder="本次会议讨论的主题"/></label><div class="form-row"><label>会议日期 <span class="required">*</span><input v-model="form.meeting_date" required type="date"/></label><label>所属项目<select v-model="form.project_id"><option value="">未归类</option><option v-for="p in ui.projects" :key="p.id" :value="p.id" :disabled="isProjectReadOnly(p.id)&&p.id!==form.project_id">{{p.name}}</option></select></label></div><label>地点<input v-model="form.location" maxlength="500" placeholder="会议室或线上会议方式（可选）"/></label><label>参会人<ProjectAttendees v-model="form.attendees" :project-id="form.project_id" :disabled="busy||readonly"/></label><label for="meeting-content">纪要正文 <span class="required">*</span><span class="input-hint">Markdown 格式，可写讨论、决定和后续安排。</span></label></div><textarea id="meeting-content" v-model="form.content" class="markdown-editor" required maxlength="200000" spellcheck="false" placeholder="## 讨论事项&#10;&#10;## 会议决定&#10;&#10;## 后续安排"/></fieldset></form><div class="editor-footer">{{editing?'已保存版本 '+editing.version:'尚未保存到数据库'}}<span>{{form.content.length}} 字</span></div><HistoryPanel v-if="editing" kind="meeting-minutes" :id="editing.id" :revision="editing.version"/></template><div v-else class="empty-state editor-empty"><FilePenLine :size="40"/><h2>把讨论与决定记在一起</h2><p>新建纪要，或从左侧打开已保存的会议记录。</p><button type="button" class="button primary" @click="create"><Plus :size="16"/>新建纪要</button></div></section></div>
</template>
<style scoped>
.meeting-filters{flex-wrap:wrap}.meeting-filters input[type=date]{width:160px;flex:0 1 160px;font-size:12px}.meeting-filters input[placeholder]{font-size:12px}.meeting-filters input[placeholder]{flex:1;min-width:170px}.meeting-list strong{font-size:13px;line-height:1.7;overflow-wrap:anywhere}.meeting-list button{display:flex;flex-direction:column;gap:5px}.meeting-list button:disabled{cursor:wait}.meeting-editor .section-heading{align-items:flex-start}.meeting-editor .row-actions{flex-wrap:wrap;justify-content:flex-end}.meeting-fields{padding:20px 22px 0}.meeting-fields label{margin-bottom:14px}.meeting-fields label[for=meeting-content]{margin-bottom:8px}.meeting-notices:has(>*){padding:0 18px}.meeting-notices .draft-notice,.meeting-notices .conflict-notice{margin-top:14px}.meeting-editor .markdown-editor{min-height:290px}.meeting-filters .checkbox-label{margin:0;white-space:nowrap}.meeting-editor fieldset{min-width:0}.meeting-layout{align-items:start}@media(max-width:700px){.meeting-editor .section-heading{flex-direction:column;gap:12px}.meeting-editor .row-actions{justify-content:flex-start}.meeting-fields{padding:18px 16px 0}.meeting-filters input[type=date]{max-width:calc(50% - 20px)}.meeting-filters select{width:100%}}
</style>
